    # The output background is the common foreground color when both panels
    # contain the same non-background color; otherwise use the second panel's
    # background.
    ca = {x for row in a for x in row if x != ba}
    cb = {x for row in b for x in row if x != bb}
    common = ca & cb
    base = min(common) if common else bb

